Question: Write a Java program that connects to a Redis database, stores user-provided key-value pairs, and retrieves values based on the provided keys. The program should use command-line arguments for specifying the Redis server's IP address and port number.
PLAINFORMAT

<think>import redis.clients.jedis.Jedis;

import java.util.Scanner;

public class RedisConnection {
    public static void main(String[] args) {
        if (args.length != 2) {
            System.err.println("Usage: java RedisConnection <IP_ADDRESS> <PORT_NUMBER>");
            return;
        }

        String ipAddress = args[0];
        int portNumber;

        try {
            portNumber = Integer.parseInt(args[1]);
        } catch (NumberFormatException e) {
            System.err.println("Error: Invalid port number.");
            return;
        }

        Jedis jedis = new Jedis(ipAddress, portNumber);

        try {
            // Test connection
            jedis.ping();
        } catch (Exception e) {
            System.err.println("Error: Unable to connect to Redis server at " + ipAddress + ":" + portNumber);
            return;
        }

        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.println("\nChoose an option:");
            System.out.println("1. Store key-value pair");
            System.out.println("2. Retrieve value by key");
            System.out.println("3. Exit");

            int choice = scanner.nextInt();
            scanner.nextLine(); // Consume newline character

            switch (choice) {
                case 1:
                    System.out.print("Enter key: ");
                    String key = scanner.nextLine();

                    System.out.print("Enter value: ");
                    String value = scanner.nextLine();

                    jedis.set(key, value);
                    System.out.println("Key-value pair stored successfully.");
                    break;

                case 2:
                    System.out.print("Enter key: ");
                    key = scanner.nextLine();

                    value = jedis.get(key);

                    if (value == null) {
                        System.out.println("No value found for the given key.");
                    } else {
                        System.out.println("Value: " + value);
                    }
                    break;

                case 3:
                    scanner.close();
                    jedis.close();
                    return;

                default:
                    System.out.println("Invalid option. Please try again.");
            }
        }
    }
}</think>

